$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
Add-Type -AssemblyName System.IO.Compression
$path=Join-Path $PSScriptRoot 'Chapter 3.docx'
Copy-Item -LiteralPath $path -Destination (Join-Path $env:TEMP 'CAPSTONE-Chapter-3-before-content-audit.docx') -Force
$zip=[IO.Compression.ZipFile]::Open($path,[IO.Compression.ZipArchiveMode]::Update)
try {
 $entry=$zip.GetEntry('word/document.xml');$stream=$entry.Open();$reader=[IO.StreamReader]::new($stream);[xml]$doc=$reader.ReadToEnd();$reader.Dispose();$stream.Dispose()
 $ns=[Xml.XmlNamespaceManager]::new($doc.NameTable);$ns.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
 function GetText($node){(($node.SelectNodes('.//w:t',$ns)|ForEach-Object InnerText)-join '')}
 function SetText($node,[string]$value){$texts=@($node.SelectNodes('.//w:t',$ns));if(-not $texts.Count){throw 'Target node has no text.'};$texts[0].InnerText=$value;for($i=1;$i -lt $texts.Count;$i++){$texts[$i].InnerText=''}}
 $changes=[ordered]@{}
 $changes.Add('Data process modeling illustrates how data flows within the IronGrind System.','The data-process model follows information from an actor, through an authorized system function, to the records it reads or changes. Applicant registration and renewal requests are reviewed before they create or update member and payment records. Attendance scans are checked against the member and any open visit before timestamps and operator identities are stored. Product sales read catalog and stock data, then save transaction lines and deduct stock. Reports and activity logs are separate read operations with different access rules.')
 $changes.Add('In this study, diagrams serve as visual representations that illustrate how data and processes flow within the Iron Grind Fitness Gym Membership & Operations Management System.','The diagrams answer different design questions: the context diagram shows the system boundary and its actors; the Level 1 DFD traces actor inputs through processes to data stores; the use-case diagram summarizes role permissions; and the physical ERD shows declared table relationships. Interface figures are prototypes, while the Gantt chart records a planned schedule. No one diagram replaces the implementation or its authorization rules.')
 $changes.Add('In addition, each diagram contributes to identifying potential areas for improvement by highlighting connections, dependencies, and overall workflow behavior.','Read the diagrams together to follow the same operation at different levels. For example, a member renewal begins as an authenticated request, enters the pending-request review process, and on approval updates the application, member dates, history, and transaction records. The diagrams describe the documented design; the workflow explanations and data dictionary identify its implementation boundaries and current limits.')
 $changes.Add('These use cases outline the specific actions, such as managing membership information, updating records, and generating reports, that contribute to the system''s overall functionality.','End-to-end system flow. Each protected operation begins with authentication and an active-role check. Page visibility alone does not authorize a database change; database policies, role-checked functions, or authorized server-side services validate privileged operations.')
 $changes.Add('It also serves as a blueprint for system design, making it easier to implement, test, and maintain the system.','1. Applicant account and request. A prospective member creates an account with email and password through Supabase Auth before the online application is reviewed. The application is stored separately with its applicant account link and a pending status. Submission alone does not create an approved member record or active membership.')
 $changes.Add('Administrator and staff permissions are shown separately.','2. Review and membership activation. Authorized staff or an administrator loads limited pending-request details, confirms that payment was received at the gym, and chooses approve or reject. The server rechecks the active role, locks the pending request, and prevents a second review. Rejection records the decision. Approval of registration creates the member record linked to the existing Auth account; approval of renewal updates the membership dates. Approved requests also record the membership transaction, and renewals add a membership-history event.')
 $changes.Add('The User is responsible for managing their personal profile, submitting membership applications and renewals, and viewing their attendance history.','3. Member self-service. A member signs in with email to view their own membership, progress, QR code, attendance history, and active catalog. They may update permitted personal details and submit a renewal request. A member can access only their own records; administrator profile viewing is read-only, and staff have no member-profile viewing or editing permission.')
 $changes.Add('Administrators review online applications and renewal requests and manage membership records, products, stock, staff access, phone pairings, activity logs, and reports. Staff record attendance, register walk-in members, perform permitted direct membership changes, record product sales, and review their own product-sale records.','4. Counter and attendance operations. For walk-in registration, authorized staff or an administrator enters the separate name fields and membership details; a server-side service creates the required account, profile, member, and transaction records. Direct renewal and active-plan change use limited member lookup and an authorized function, not a member-profile screen. For attendance, an authenticated operator scans the member QR; the service checks the member and existing open visit, then records check-in or check-out with its timestamp and operator. Phone pairing is administrator-managed and remains separate from operator sign-in. An earlier-date visit without check-out is shown as Incomplete without inventing an exit time.')
 $changes.Add('Each of these processes represents a key function of the system, ensuring that gym information is accurately maintained, updated, and easily accessible.','5. Products, sales, and oversight. Administrators maintain the catalog, prices, product units, stock, and active state. Members and staff read only the catalog permitted for their role. When an operator records an in-person product sale, the service validates the item, unit, and available stock, saves the sale and line item, and deducts the quantity. IronGrind records payment at the gym but does not issue a customer receipt. Staff may review their own product sales. Administrators separately generate reports and read filtered activity logs; the log viewer does not perform the logged operations.')
 $changes.Add('Table 6: profilesssssss','Table 6: profiles')
 $changes.Add('Figure 20. Staff operations and access','Figure 20. Staff workflow and access limits')
 $changes.Add('Staff Operations. Figure 20 summarizes staff attendance, counter registration, direct subscription renewal, active-member plan change, online registration and renewal request approval, product sales, and own-sales review, while distinguishing administrator-only controls. It is a workflow illustration rather than a captured interface. The earlier receipt illustration has been replaced to match the stated transaction-recording scope.','Staff workflow. Figure 20 follows staff sign-in through attendance, request review, counter membership service, and product-sale recording. It shows the server checks and records involved and marks functions reserved for administrators. It is a workflow illustration, not a captured interface.')
 $changes.Add('2. Register and Submit Membership Application. This function allows a member to create an account using an email address and password, then submit personal and health information for review by authorized staff or the administrator. Name fields accept names containing letters and reject numeric characters.','2. Register and Submit Membership Application. An applicant creates an account using an email address and password, then submits personal and health information for review by authorized staff or the administrator. Name fields accept names containing letters and reject numeric characters.')
 $changes.Add('9. View Personal Attendance History The User can view a detailed log of their own gym visits, including the dates and exact times they entered and exited the gym.','9. View Personal Attendance History. A member can view their own visit dates and recorded check-in and check-out times. A visit without a recorded check-out does not display an invented exit time.')
 $changes.Add('1. auth.users Entity This entity serves as the primary authentication table for the system. It stores the unique identifier (id) and email address of every user. This entity is crucial for system security, ensuring that only individuals with verified credentials can log in and access the system.','1. auth.users Entity. Supabase Auth manages this account table. Its user identifier links application records to the authenticated identity; Auth verifies sign-in credentials, while IronGrind role and active-account checks determine which protected functions the account may use.')
 $changes.Add('3. membership_applications Entity This table stores data from new applicants and renewal requests awaiting review by authorized staff or the administrator. It tracks the application type, selected plan, current status, and submission time. It links to the user applying (auth_user_id) and the staff member or administrator who reviewed it (reviewed_by).','3. membership_applications Entity. This table stores submitted registration and renewal requests and retains them after review. It records request type, selected plan, status, submission time, and, after review, the reviewer and decision time. Registration requests link to the applicant Auth account; renewal requests also link to the existing member.')
 $changes.Add('Members to Membership Applications. This is a one-to-many relationship: a member can have multiple membership applications over time, including renewal requests. Each application may reference one member. A pending registration application can exist without a linked member record until it is processed.','Members to Membership Applications. Renewal applications may reference one existing member. A new registration application has no member_id; after approval, the new member record instead references its source application through members.application_id.')
 $changes.Add('Members to Sales. This is a one-to-many relationship because a member can make multiple product purchases (sales), but each sale is tied to only one member (if it is not a walk-in).','Members to Sales. This is a one-to-many relationship: a member may be associated with multiple sales, and each sale has at most one optional member reference. Walk-in product sales can have no linked member.')
 $changes.Add('Products to Sale_Items. A product can appear in multiple sale items. Each sale item may reference one product, while membership charges have no product reference. The item name and price are retained as transaction snapshots','Products to Sale_Items. A product may appear in multiple sale items. Each sale item may reference one product, while membership charges have no product reference. The saved item name and unit price preserve the transaction details if the catalog changes or its product reference is removed.')
 $paras=@($doc.SelectNodes('//w:body/w:p',$ns))
 foreach($key in $changes.Keys){if($key -eq 'Membership Applications |' -or $key -eq 'Table 2. Input Requirements'){continue};$prefix=$key.Substring(0,[Math]::Min(100,$key.Length));$match=$paras|Where-Object {(GetText $_).StartsWith($prefix)}|Select-Object -First 1;if(-not $match){$updatedPrefix=$changes[$key].Substring(0,[Math]::Min(80,$changes[$key].Length));$already=$paras|Where-Object {(GetText $_).StartsWith($updatedPrefix)}|Select-Object -First 1;if($already){continue};throw "Paragraph not found: $prefix"};SetText $match $changes[$key]}
 $tables=@($doc.SelectNodes('//w:body/w:tbl',$ns))
 function SetCell($tableIndex,$rowIndex,$cellIndex,[string]$value){$rows=@($tables[$tableIndex].SelectNodes('w:tr',$ns));$cells=@($rows[$rowIndex].SelectNodes('w:tc',$ns));SetText $cells[$cellIndex] $value}
