 SetCell 4 9 3 'The web app uses cloud-hosted Supabase services; no minimum bandwidth has been measured.'
 $entry=$zip.GetEntry('word/document.xml');$entry.Delete();$newEntry=$zip.CreateEntry('word/document.xml',[IO.Compression.CompressionLevel]::Optimal);$out=$newEntry.Open();$settings=[Xml.XmlWriterSettings]::new();$settings.Encoding=[Text.UTF8Encoding]::new($false);$writer=[Xml.XmlWriter]::Create($out,$settings);$doc.Save($writer);$writer.Dispose();$out.Dispose()
}finally{$zip.Dispose()}
